import{_ as t,o as i,c as l,a2 as e}from"./chunks/framework.F7eQ-ohH.js";const r="/bzygq/assets/quesion_imgs_9d8389737a2748b7af8bc10274d7acc3.B4qyeT0A.png",o="/bzygq/assets/quesion_imgs_570661afd19943578bf6cb059365c190.4Etn2DcN.png",d="/bzygq/assets/quesion_imgs_e332c8c3349542f3b9c31b6dc3cf681d.Dy1V-INT.png",s="/bzygq/assets/quesion_imgs_e359003a138440cc907c5001813eb598.Ffg1ZeOF.png",h="/bzygq/assets/quesion_imgs_1353f20081fa4ed79986ba264c47dfde.gAWAyOF9.png",n="/bzygq/assets/quesion_imgs_83a13e658b6e4545b7fc171d61de2284.D0JJ8sti.png",P="/bzygq/assets/quesion_imgs_a3db7fae84c24cdbac37f1b957b78ead.D2AU0ss8.png",p="/bzygq/assets/quesion_imgs_50ae5b4125474f3899d4fed154b34f10.C9V8SZL3.png",c="/bzygq/assets/quesion_imgs_dabd5bc65ce44a24bb2d6d6efe22893f.B2UNQcY8.png",b="/bzygq/assets/quesion_imgs_45a2a8a70bd3479d83a279cd16defc84.B0DByVKq.png",u="/bzygq/assets/quesion_imgs_c1ab1c3b767d4d8c972a308ecf325231.DyznJaKE.png",T="/bzygq/assets/quesion_imgs_588a64e40c924f25b5fdcf9a4e04afab.CW4ClKEP.png",m="/bzygq/assets/quesion_imgs_f54b71c821a645aaae00db084b96dc6f.BrwHY4x8.png",C="/bzygq/assets/quesion_imgs_028ec69d49984563b3edd4916fd35dbf.Y-7AtQWe.png",I="/bzygq/assets/quesion_imgs_5daee5a1bf314b4397cb36c2b928e5b1.AFx1F4FU.png",q="/bzygq/assets/quesion_imgs_bbe16244b36949d5add49d507a67cf24.ZNUmOYO2.png",g="/bzygq/assets/quesion_imgs_3f53742620394ae9b05badef6ea7522d.C2R8lAsv.png",_="/bzygq/assets/quesion_imgs_53d7e6c0d36a4c03aa565a293ec1e15a.DE4z3c6V.png",S="/bzygq/assets/quesion_imgs_77fa717179dd4b149a843ddc4cd9622c.BFSweIHV.png",U=JSON.parse('{"title":"Part 02：计算机网络体系结构","description":"","frontmatter":{},"headers":[],"relativePath":"科技岗专业课/计算机网络/2、计算机网络体系结构.md","filePath":"科技岗专业课/计算机网络/2、计算机网络体系结构.md","lastUpdated":1788883925000}'),y={name:"科技岗专业课/计算机网络/2、计算机网络体系结构.md"};function f(D,a,x,k,A,O){return i(),l("div",null,[...a[0]||(a[0]=[e('<h1 id="part-02-计算机网络体系结构" tabindex="-1"><strong>Part 02：计算机网络体系结构</strong> <a class="header-anchor" href="#part-02-计算机网络体系结构" aria-label="Permalink to &quot;**Part 02：计算机网络体系结构**&quot;">​</a></h1><table tabindex="0"><thead><tr><th>【原创声明】大家好，我是say，是这篇文章的原创作者！985硕士毕业，应届进入某大厂后道心破碎，社招上岸多家855半垄断央企，因为自己淋过雨，希望帮大家撑把伞，帮助更多同学找到不内卷、能够好好生活的央国企，已帮助1000+同学上岸央国企，需要连联系学长的加微信：wx_hxsay</th></tr></thead></table><h2 id="计算机网络的分层" tabindex="-1">计算机网络的分层 <a class="header-anchor" href="#计算机网络的分层" aria-label="Permalink to &quot;计算机网络的分层&quot;">​</a></h2><h2 id="什么是计算机网络分层" tabindex="-1">什么是计算机网络分层？ <a class="header-anchor" href="#什么是计算机网络分层" aria-label="Permalink to &quot;什么是计算机网络分层？&quot;">​</a></h2><p><img src="'+r+'" alt=""></p><p>在理解计算机网络为什么需要分层之前，大家可以想一下一个公司是不是会分成多个部门，各司其职？计算机网络也一样，通过将复杂的网络通信功能，按照功能逻辑拆解为多个相互独立且有序的层次模块的设计方法。每个层次都专注于实现特定的核心功能，通过层间接口与相邻层次交互，最终协同完成端到端的网络通信任务。简单来说，它就像 “分工协作” 的工作模式，每个 “部门”（层次）负责专属任务，通过标准化的 “对接流程”（接口）配合，实现整体目标。</p><h2 id="为什么要给计算机网络分层" tabindex="-1">为什么要给计算机网络分层？ <a class="header-anchor" href="#为什么要给计算机网络分层" aria-label="Permalink to &quot;为什么要给计算机网络分层？&quot;">​</a></h2><p>就像公司分部门设计可以更好的管理员工，让所有人各司其职一样，计算机网络的分层设计的核心目的是解决网络系统复杂性带来的设计、实现与维护难题，主要优势体现在两方面：</p><ol><li>简化开发与维护流程：将庞大的网络系统拆解为多个小模块后，开发人员可聚焦单一层次的功能实现（比如仅专注 “数据传输” 或 “应用交互”），无需关注整个系统的复杂关联，降低设计难度；后续系统更新（如升级传输技术）或故障排查时，只需针对对应层次操作，不影响其他模块，提升维护效率。</li><li>增强系统独立性与适应性：每层都有明确的功能边界和服务范围，仅依赖下一层提供的 “基础服务”，同时为上一层提供 “特定服务”。例如，数据链路层技术从以太网升级为 Wi-Fi 时，只要保持与物理层、网络层的接口不变，网络层及以上层次的功能就不受影响，大幅提升了系统对技术迭代的适应能力。</li></ol><h2 id="计算机网络分层的原则" tabindex="-1">计算机网络分层的原则 <a class="header-anchor" href="#计算机网络分层的原则" aria-label="Permalink to &quot;计算机网络分层的原则&quot;">​</a></h2><ol><li>边界清晰化：各层次的功能范围和职责边界需明确界定，避免功能重叠或遗漏，便于开发、理解和调试。例如，物理层仅负责 “比特流的物理传输”，数据链路层负责 “帧的封装与差错控制”，两者边界清晰，无交叉职责。</li><li>功能独立性：每层的实现方式可自主迭代优化，只要保持与上下层的接口标准不变，就不会影响相邻层次的正常运行。比如传输层的 TCP 协议可优化拥塞控制算法，无需修改应用层的 HTTP 协议或网络层的 IP 协议。</li><li>适配国际标准：分层设计需为国际通用协议的制定提供框架，确保不同国家、不同厂商的网络设备（如华为路由器、思科交换机）遵循统一的接口和协议规范，实现跨设备、跨网络的兼容互通。</li><li>层数合理化：层数过少会导致单个层次承担的功能过多，协议设计复杂；层数过多则会增加层间交互的开销，降低系统效率。例如，OSI 的七层结构因层数偏多，实际应用中逐步被更精简的 TCP/IP 四层结构替代。</li></ol><h2 id="计算机网络体系结构" tabindex="-1">计算机网络体系结构 <a class="header-anchor" href="#计算机网络体系结构" aria-label="Permalink to &quot;计算机网络体系结构&quot;">​</a></h2><h3 id="体系结构的定义" tabindex="-1">体系结构的定义 <a class="header-anchor" href="#体系结构的定义" aria-label="Permalink to &quot;体系结构的定义&quot;">​</a></h3><p><img src="'+o+'" alt=""></p><p>计算机网络体系结构是对网络分层设计的规范化描述，核心是 “层 + 协议 + 层间接口” 的集合，具体包含三部分核心内容：</p><ul><li>分层结构及各层的功能定位（明确每层 “做什么”）；</li><li>层间接口规范（定义相邻层次如何交互，即 “怎么传”）；</li><li>各层对应的协议（规定同层次设备间的通信规则，即 “按什么规则传”）。</li></ul><p>通过以上三个部分的划分，可以明确各个层级之间的功能和应当遵守的协议，确保计算机网络之间的各个层次各司其职。</p><h3 id="主流标准体系结构" tabindex="-1">主流标准体系结构 <a class="header-anchor" href="#主流标准体系结构" aria-label="Permalink to &quot;主流标准体系结构&quot;">​</a></h3><p><img src="'+d+'" alt=""></p><p>目前计算机网络领域有两种核心体系结构，分别对应不同的应用场景：</p><ol><li>ISO/OSI 七层体系结构</li></ol><p>由国际标准化组织（ISO）提出，是理论性的网络模型，为网络设计提供了全面的逻辑框架，从下到上依次为：</p><ul><li>物理层：负责比特流的物理传输（如网线、光纤的信号传输）；</li><li>数据链路层：对物理层传输的比特流进行帧封装，并处理传输差错；</li><li>网络层：实现不同网络间的路由选择和数据转发（核心是 IP 地址寻址）；</li><li>传输层：为端到端应用提供可靠或不可靠的传输服务（如 TCP 的可靠传输、UDP 的实时传输）；</li><li>会话层：建立、管理和终止应用程序间的通信会话；</li><li>表示层：处理数据的格式转换、加密解密、压缩解压（如将文本转换为二进制）；</li><li>应用层：为具体应用程序提供网络接口（如 HTTP 对应网页浏览、FTP 对应文件传输）。</li></ul><p>特点：功能划分细致、理论完备，但因层次过多、实现复杂，未在实际应用中广泛落地。</p><ol><li>TCP/IP 四层体系结构</li></ol><p>源于互联网的实践需求，是目前全球最主流的实际应用体系结构，从下到上依次为：</p><ul><li>网络接口层：对应 OSI 的物理层和数据链路层，负责本地网络的物理传输和帧处理；</li><li>网络层：核心是 IP 协议，实现跨网络的路由转发和地址寻址，与 OSI 网络层功能一致；</li><li>传输层：包含 TCP 和 UDP 协议，为应用提供端到端传输服务，与 OSI 传输层功能一致；</li><li>应用层：整合了 OSI 的会话层、表示层和应用层功能，直接为应用程序提供通信服务，包含 HTTP、FTP、DNS 等主流协议。</li></ul><p>特点：层次精简、实现灵活、兼容性强，是互联网的核心技术框架，所有联网设备均遵循该体系结构进行通信。</p><ol><li>TCP/IP 五层模型</li></ol><p>TCP/IP 五层模型是在四层模型基础上，将网络接口层进一步拆分为物理层和数据链路层，形成更贴近实际硬件实现的分层框架。该模型在教学和理论分析中被广泛使用，既保留了 TCP/IP 的简洁性，又细化了底层通信细节。</p><ul><li>物理层：负责比特流的物理传输（如网线、光纤的信号传输）；</li><li>数据链路层：对物理层传输的比特流进行帧封装，并处理传输差错；</li><li>网络层：核心是 IP 协议，实现跨网络的路由转发和地址寻址，与 OSI 网络层功能一致；</li><li>传输层：包含 TCP 和 UDP 协议，为应用提供端到端传输服务，与 OSI 传输层功能一致；</li><li>应用层：整合了 OSI 的会话层、表示层和应用层功能，直接为应用程序提供通信服务，包含 HTTP、FTP、DNS 等主流协议。</li></ul><p>五层的TCP/IP体系结构是学历和考试中更为常见的计算机网络的体系结构模型！</p><h2 id="practices" tabindex="-1">Practices <a class="header-anchor" href="#practices" aria-label="Permalink to &quot;Practices&quot;">​</a></h2><table tabindex="0"><thead><tr><th>【例题】下列关于计算机网络主流体系结构的说法，正确的是（ ）A. ISO/OSI七层体系结构因功能精简、实现灵活，是目前互联网的核心技术框架B. TCP/IP四层体系结构的网络接口层对应OSI模型的物理层C. TCP/IP五层模型在教学和理论分析中应用广泛，且细化了底层通信细节D. OSI七层体系结构的应用层整合了会话层和表示层的功能答案：C解析：A选项错误，TCP/IP四层体系结构才是目前互联网的核心技术框架，OSI七层因层次过多未广泛落地；B选项错误，TCP/IP四层的网络接口层对应OSI的物理层和数据链路层；C选项正确，材料明确提到TCP/IP五层模型在教学和理论分析中广泛使用，且拆分了网络接口层，细化底层细节；D选项错误，整合会话层、表示层功能的是TCP/IP体系结构的应用层，而非OSI七层的应用层。</th></tr></thead></table><table tabindex="0"><thead><tr><th>【例题】计算机网络中，负责为端到端应用提供可靠或不可靠传输服务的层次是（ ）A. 网络层B. 传输层C. 应用层D. 数据链路层答案：B解析：根据材料内容，传输层包含TCP（可靠传输）和UDP（实时传输，不可靠）协议，核心功能是为应用提供端到端的传输服务；网络层主要负责路由选择和IP寻址；应用层为具体应用程序提供网络接口；数据链路层负责帧封装和差错控制，因此正确答案为B。</th></tr></thead></table><h2 id="协议、接口、服务" tabindex="-1">协议、接口、服务 <a class="header-anchor" href="#协议、接口、服务" aria-label="Permalink to &quot;协议、接口、服务&quot;">​</a></h2><p><img src="'+s+'" alt=""></p><p>在计算机网络分层体系结构中，协议、接口、服务是三个核心基础概念，三者相互关联又边界清晰，共同支撑起分层网络的有序运行。</p><ol><li>实体：能发或收信息的硬件或软件进程，比如电脑里的某个程序，或者路由器这种硬件，能传信息的都算。</li><li>对等层：两个不同系统的同一层，比如系统 A 的第二层和系统 B 的第二层，就是对等层。</li><li>对等实体：不同系统对等层里的两个实体，比如系统 A 第二层的某个程序和系统 B 第二层的某个程序，互为对等实体。</li><li>接口：相邻两层之间的交互界面，规定了两层之间咋操作，下层给上层提供啥服务，就像上下楼的楼梯口，规定了怎么从下层到上层。</li><li>服务：某一层及其下面各层的能力，通过接口给上层用，比如下层能传输数据，上层通过接口就能用这个传输能力。</li><li>协议：通信双方必须遵守的规则，规定了发和收报文的格式、顺序，还有传送接收时的动作。协议有三个要素：</li></ol><ul><li>语义：控制信息每个部分啥意思，该发啥控制信息，做啥动作、啥响应，比如告诉对方 “这个信息是请求”，对方就知道要回应。</li><li>语法：用户数据和控制信息的结构、格式，比如数据要按什么格式排列，像信封的格式。</li><li>时序：事件发生的顺序，也就是同步，比如先发请求，再收响应，顺序不能乱。</li></ul><p>关于协议、接口和服务之间的区别，按照如下表格所示：</p><table tabindex="0"><thead><tr><th>概念</th><th>定义核心</th><th>作用对象</th><th>核心特点</th></tr></thead><tbody><tr><td>协议</td><td>同层通信的规则</td><td>对等实体（同层）</td><td>关注 “同层如何传”，保障通信一致性</td></tr><tr><td>接口</td><td>相邻层的交互边界</td><td>相邻层（上下层）</td><td>关注 “上下层如何对接”，隐藏实现细节</td></tr><tr><td>服务</td><td>下层向上层提供的功能</td><td>相邻层（上下层）</td><td>关注 “下层给上层提供什么能力”</td></tr></tbody></table><p>总之，协议、接口、服务是计算机网络分层设计的三大支柱：协议规范了同层的通信逻辑，接口定义了上下层的交互标准，服务实现了层间的功能支撑。理解三者的区别与联系，是掌握网络体系结构、分析网络协议工作原理的关键基础，也为网络故障排查、协议设计提供了核心逻辑框架。</p><h2 id="协议" tabindex="-1">协议 <a class="header-anchor" href="#协议" aria-label="Permalink to &quot;协议&quot;">​</a></h2><h3 id="协议三要素" tabindex="-1">协议三要素 <a class="header-anchor" href="#协议三要素" aria-label="Permalink to &quot;协议三要素&quot;">​</a></h3><p><img src="'+h+'" alt=""></p><p>在计算机网络中，协议是通信双方必须遵守的一套规则和约定，以确保数据能够正确、高效地传输。协议的核心由三个基本要素构成：<strong>语法（Syntax）、语义（Semantics）和时序（Timing）</strong>，它们共同定义了通信过程中的数据格式、功能逻辑以及操作顺序。</p><p>语法规定了数据的结构和格式，确保通信双方能够正确解析传输的信息。它定义了数据的编码方式（如二进制、ASCII或Unicode）、数据的组织单位（如位、字节、帧或数据包）以及控制信息的格式（如头部和尾部的结构）。例如，在HTTP协议中，请求和响应的格式必须遵循严格的语法规则，包括请求行、头部字段和消息体的排列方式，否则接收方将无法正确解析数据。</p><p>语义则定义了协议的功能逻辑，即通信双方如何理解数据并采取相应的操作。它涵盖了控制信息的含义（如HTTP中的GET、POST请求或TCP中的SYN、ACK标志）、协议支持的操作（如建立连接、传输数据或终止会话）以及对各种操作的响应（如成功、失败或重试）。例如，在TCP协议中，SYN标志表示请求建立连接，而ACK标志用于确认数据接收，这些语义规则确保了双方能够正确理解彼此的意图并执行相应的动作。</p><p>时序则规定了协议操作的执行顺序和时间约束，确保通信过程按照正确的逻辑进行。它定义了操作的先后顺序（如TCP的三次握手过程）、时间限制（如超时重传机制）以及同步机制（如序列号和确认机制）。例如，在TCP连接建立过程中，客户端首先发送SYN报文，服务器回应SYN+ACK，客户端再发送ACK确认，这一严格的时序要求确保了连接的可靠建立。如果时序混乱，可能导致连接失败或数据丢失。</p><p>总之，语法、语义和时序共同构成了网络协议的基础。语法确保数据格式的正确性，语义保证功能的逻辑性，而时序则维护操作的顺序性和同步性。这三者缺一不可，只有同时满足，才能实现高效、可靠的网络通信。无论是底层的TCP/IP协议，还是上层的HTTP、FTP等应用层协议，都依赖于这三个要素的协同作用，以确保数据在网络中的准确传输和正确处理。</p><h3 id="协议数据单元" tabindex="-1">协议数据单元 <a class="header-anchor" href="#协议数据单元" aria-label="Permalink to &quot;协议数据单元&quot;">​</a></h3><p>协议数据单元（PDU）是网络分层模型中，每一层与对等层通信时传输的数据单元，包含该层的控制信息和上层传递的数据。各层 PDU 的名称和结构不同，是理解网络通信的核心载体。</p><h4 id="pdu-的组成结构" tabindex="-1">PDU 的组成结构 <a class="header-anchor" href="#pdu-的组成结构" aria-label="Permalink to &quot;PDU 的组成结构&quot;">​</a></h4><p><img src="'+n+'" alt=""></p><p>每个 PDU 由头部（Header）、 有效载荷（Payload）和尾部（Trailer，可选） 组成：</p><ul><li>头部：包含本层协议的控制信息（如源 / 目的地址、协议类型、序列号等）。</li><li>有效载荷：上层传递的数据（即上层 PDU 的完整内容）。</li><li>尾部：部分层（如数据链路层）添加校验码（如 CRC）用于错误检测。</li></ul><p>在计算机网络体系结构中，每一层都会有自己的协议数据单元（PDU），每一层PDU会额外添加本层的头部信息并携带上一层的PDU信息来组成本层的PDU，具体如下图所示：</p><p><img src="'+P+'" alt=""></p><p>应用层的原始数据（比如QQ聊数据、游戏操作数据等）直接传送到传输层，传输层会为其封装一个TCP头部，然后再传递给网络层，而网络层则会为上一层的数据封装一个IP头部，以此类推直到最后的数据链路层。</p><h3 id="协议数据传输过程" tabindex="-1">协议数据传输过程 <a class="header-anchor" href="#协议数据传输过程" aria-label="Permalink to &quot;协议数据传输过程&quot;">​</a></h3><p>计算机网络中，数据的传输就像快递传输包裹一样，发送端需要将包裹进行打包，写上接收方地址和一些其它信息发送给接收端，然后中间通过汽车、飞机等物流送到接收端，接收端拿到包裹之后再将包裹拆开取到里面的东西。</p><p><img src="'+p+'" alt=""></p><p>计算机网络的数据传输过程也一样，简单来说数据传输过程是 封装（发送端）与解封装（接收端）的循环，通过逐层添加或剥离 PDU 头部 / 尾部，实现端到端通信。以下以 TCP/IP 五层模型为例，结合实际场景说明：</p><h4 id="数据封装过程-装快递-应用层→物理层" tabindex="-1">数据封装过程（装快递：应用层→物理层） <a class="header-anchor" href="#数据封装过程-装快递-应用层→物理层" aria-label="Permalink to &quot;数据封装过程（装快递：应用层→物理层）&quot;">​</a></h4><ol><li>应用层：</li></ol><ul><li>生成原始数据（如 HTTP 请求报文），称为 “数据”（Data），不添加头部，直接传递给传输层。</li></ul><ol><li>传输层（TCP 协议）：</li></ol><ul><li>将应用层数据分割为多个段（Segment），每个段添加 TCP 头部（含端口号、序列号等）。</li><li>例如，HTTP 使用 80 端口，源端口随机选择（如 1030），目的端口为 80。</li><li>PDU 名称：段（Segment）。</li></ul><ol><li>网络层（IP 协议）：</li></ol><ul><li>将 TCP 段封装为 IP 数据包（Packet），添加 IP 头部（含源 IP 和目的 IP 地址）。</li><li>若目标 IP 不在本地网络，通过 ARP 协议获取网关 MAC 地址。</li><li>PDU 名称：包（Packet）。</li></ul><ol><li>数据链路层（以太网协议）：</li></ol><ul><li>将 IP 数据包封装为帧（Frame），添加 MAC 头部（源 MAC 为发送方，目的 MAC 为网关）和 CRC 尾部。</li><li>例如，若网关 MAC 为 “00-11-BC-7D-25-03”，则帧头包含该地址。</li><li>PDU 名称：帧（Frame）。</li></ul><ol><li>物理层：</li></ol><ul><li>将帧转换为比特流（Bit），通过物理介质（如网线）传输。</li><li>信号编码方式（如曼彻斯特编码）由物理层协议决定。</li></ul><h4 id="数据转发与路由-送快递" tabindex="-1">数据转发与路由（送快递） <a class="header-anchor" href="#数据转发与路由-送快递" aria-label="Permalink to &quot;数据转发与路由（送快递）&quot;">​</a></h4><ol><li>路由器处理：</li></ol><ul><li>接收比特流，重组为帧，剥离 MAC 头部，校验 CRC。</li><li>提取 IP 数据包，检查目的 IP 地址，若非本机则查询路由表，确定下一跳。</li><li>重新封装数据链路层帧：源 MAC 改为路由器出接口 MAC，目的 MAC 为下一跳设备 MAC（如另一路由器或目标主机）。</li><li>网络层 TTL 字段减 1，若为 0 则丢弃数据包并返回 ICMP 超时消息。</li></ul><ol><li>跨网段传输：</li></ol><ul><li>数据包经过多个路由器转发，每次转发时数据链路层帧头的 MAC 地址更新为下一跳设备的 MAC，而 IP 头的源 / 目的 IP 保持不变。</li></ul><h4 id="数据解封装过程-收快递-物理层→应用层" tabindex="-1">数据解封装过程（收快递：物理层→应用层） <a class="header-anchor" href="#数据解封装过程-收快递-物理层→应用层" aria-label="Permalink to &quot;数据解封装过程（收快递：物理层→应用层）&quot;">​</a></h4><ol><li>物理层：</li></ol><ul><li>接收比特流，转换为连续的帧，传递给数据链路层。</li></ul><ol><li>数据链路层：</li></ol><ul><li>剥离 MAC 头部和 CRC 尾部，校验数据完整性。</li><li>提取 IP 数据包，根据头部的类型字段（如 0x0800 表示 IPv4）传递给网络层。</li></ul><ol><li>网络层：</li></ol><ul><li>剥离 IP 头部，检查目的 IP 是否为本机地址。</li><li>根据协议字段（如 6 表示 TCP）将段传递给传输层。</li></ul><ol><li>传输层（TCP 协议）：</li></ol><ul><li>剥离 TCP 头部，根据端口号确定应用程序（如 80 端口对应 HTTP）。</li><li>若为 TCP，处理确认、重传、排序等逻辑，重组完整的应用层数据。</li></ul><ol><li>应用层：</li></ol><ul><li>解析数据（如 HTTP 响应），呈现给用户（如浏览器渲染网页）。</li></ul><h2 id="practics" tabindex="-1">Practics <a class="header-anchor" href="#practics" aria-label="Permalink to &quot;Practics&quot;">​</a></h2><table tabindex="0"><thead><tr><th>【例题】以下不属于计算机网络协议三大核心要素的是（ ）A. 语法B. 语义C. 时序D. 结构答案：D解析：根据材料内容，协议的三个核心要素明确为语法、语义和时序。语法规定数据结构与格式，语义定义控制信息含义及对应操作，时序规范操作顺序与时间约束；“结构”并非独立的协议要素，其相关内容已包含在语法的定义中，因此正确答案为D。</th></tr></thead></table><table tabindex="0"><thead><tr><th>【例题】在TCP/IP五层模型中，网络层对应的协议数据单元（PDU）名称是（ ）A. 段（Segment）B. 包（Packet）C. 帧（Frame）D. 比特流（Bit）答案：B解析：材料明确说明各层对应的PDU名称：传输层的PDU是段（Segment），网络层的PDU是包（Packet），数据链路层的PDU是帧（Frame），物理层的传输形式是比特流（Bit）。因此网络层对应的PDU名称为包，正确答案为B。</th></tr></thead></table><h2 id="osi参考模型和tpc-ip参考模型" tabindex="-1">OSI参考模型和TPC/IP参考模型 <a class="header-anchor" href="#osi参考模型和tpc-ip参考模型" aria-label="Permalink to &quot;OSI参考模型和TPC/IP参考模型&quot;">​</a></h2><h2 id="osi-参考模型-7-层" tabindex="-1">OSI 参考模型 7 层 <a class="header-anchor" href="#osi-参考模型-7-层" aria-label="Permalink to &quot;OSI 参考模型 7 层&quot;">​</a></h2><p><img src="'+c+'" alt=""></p><p>OSI（Open System Interconnection）七层体系结构是由国际标准化组织（ISO）于 1981 年提出的网络通信参考模型，旨在为异构系统互联提供统一的逻辑框架。它将网络通信功能划分为七个层次，每层专注于特定任务，并通过标准化接口与相邻层交互，这七个层次分别是应用层、表示层、会话层、传输层、网络层、数据链路层和物理层，后文将就这几个层次详细介绍。</p><h3 id="物理层-physical-layer" tabindex="-1">物理层（Physical Layer） <a class="header-anchor" href="#物理层-physical-layer" aria-label="Permalink to &quot;物理层（Physical Layer）&quot;">​</a></h3><p><img src="'+b+'" alt=""></p><p>物理层的设备主要包括集线器、中继器等，数据的传输单位是比特流，负责在物理介质（如电缆、光纤、无线信号）上传输比特流，定义物理设备的电气、机械和规程特性。例如，规定网线接口类型（如 RJ45）、信号编码方式（如曼彻斯特编码）及传输速率（如 100Mbps）。</p><ul><li>关键协议与设备：</li><li>协议：RS-232（串口通信）、IEEE 802.3（以太网物理层）、V.35（广域网接口）。</li><li>设备：集线器（Hub）、中继器（Repeater）、光纤收发器。</li><li>特点：不关心数据的逻辑含义，仅确保信号可靠传输，是网络通信的物理基础。</li></ul><h3 id="数据链路层-data-link-layer" tabindex="-1">数据链路层（Data Link Layer） <a class="header-anchor" href="#数据链路层-data-link-layer" aria-label="Permalink to &quot;数据链路层（Data Link Layer）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>网卡</th><th>网桥</th><th>交换机</th></tr></thead></table><p>数据链路层的设备主要包括：网卡、网桥、交换机，数据的传输单位则是帧（frame）。数据链路层在不可靠的物理介质上提供可靠的传输。该层的作用包括物理地址寻址、数据的成帧、流量控制、数据的检错、重发等。将物理层的比特流封装成帧，实现相邻节点间的可靠传输，主要包括：</p><ul><li>差错检测：通过 CRC 校验码检测传输错误</li><li>流量控制：避免发送方速度过快导致接收方缓冲区溢出</li><li>介质访问控制：协调多设备对共享介质的访问（如以太网的 CSMA/CD 协议）</li><li>关键协议与设备：</li><li>协议：HDLC（高级数据链路控制）、PPP（点对点协议）、以太网 MAC 协议</li><li>设备：交换机（Switch）、网桥（Bridge）</li></ul><h3 id="网络层-network-layer" tabindex="-1">网络层（Network Layer） <a class="header-anchor" href="#网络层-network-layer" aria-label="Permalink to &quot;网络层（Network Layer）&quot;">​</a></h3><p><img src="'+u+'" alt=""></p><p>网络层设备主要是大家日常都会适用的——路由器，数据的最小传输单位是数据包（packet），网络层负责对子网间的数据包进行路由选择。此外，网络层还可以实现拥塞控制、网际互联等功能，实现跨网络的路由选择和寻址，确保数据从源主机到目的主机的端到端传输，其核心任务包括：</p><ul><li>IP 地址管理：分配逻辑地址（如 IPv4、IPv6），屏蔽物理地址差异</li><li>路由算法：根据网络拓扑选择最优路径（如 RIP、OSPF 协议）</li><li>分片与重组：当数据包超过链路 MTU 时进行分割，并在接收端重组</li><li>关键协议与设备：</li><li>协议：IP（网际协议）、ICMP（网络控制报文协议）、ARP（地址解析协议）</li><li>设备：路由器（Router）、三层交换机</li></ul><h3 id="传输层-transport-layer" tabindex="-1">传输层（Transport Layer） <a class="header-anchor" href="#传输层-transport-layer" aria-label="Permalink to &quot;传输层（Transport Layer）&quot;">​</a></h3><p><img src="'+T+'" alt=""></p><p>传输层则无特定设备，主要由主机操作系统实现，传输数据的单位也是数据段（segment）。传输层是第一个端到端，即主机到主机的层次。传输层负责将上层数据分段并提供端到端的、提供端到端的可靠或不可靠传输服务，屏蔽网络层的差异，确保数据准确到达，核心功能包括：</p><ul><li>连接管理：面向连接的 TCP（三次握手建立连接）和无连接的 UDP。</li><li>流量控制：通过滑动窗口机制调节数据传输速率（如 TCP 的拥塞控制）。</li><li>复用与分用：通过端口号区分同一主机上的不同应用（如 HTTP 用 80 端口）。</li><li>关键协议：</li><li>TCP（传输控制协议）：提供可靠、有序的字节流传输，适用于文件传输、网页浏览。</li><li>UDP（用户数据报协议）：无连接、低延迟，适用于视频流、DNS 查询。</li></ul><p>传输层是计算机网络中我们接触得最多得协议之一，在TCP/IP的5层和4层协议当中，均将上三层协议合并到了传输层协议当中，也是央国企笔试当中常考的知识点</p><h3 id="会话层-session-layer" tabindex="-1">会话层（Session Layer） <a class="header-anchor" href="#会话层-session-layer" aria-label="Permalink to &quot;会话层（Session Layer）&quot;">​</a></h3><p><img src="'+m+'" alt=""></p><p>和传输层一样，会话层也没有特定设备，主要由主机操作系统实现。主要功能是管理主机之间的会话进程，即负责建立、管理、终止进程之间的会话。会话层还利用在数据中插入校验点来实现数据的同步，建立、管理和终止应用程序间的会话，支持会话同步和恢复，其核心任务包括：</p><ul><li>会话控制：决定通信双方的传输模式（如全双工、半双工）。</li><li>同步点设置：在数据传输中插入校验点，故障时可从最近的同步点恢复（如断点续传）。</li><li>令牌管理：协调双方的关键操作（如数据库事务中的互斥访问）。</li></ul><p>关键协议：</p><ul><li>NetBIOS（网络基本输入 / 输出系统）：早期局域网会话管理。</li><li>RPC（远程过程调用）：允许程序调用远程主机的服务。</li></ul><p>会话层协议的实际应用较少，部分功能被传输层（如 TCP 的连接管理）或应用层协议（如 HTTP 的短连接）替代。</p><h3 id="表示层-presentation-layer" tabindex="-1">表示层（Presentation Layer） <a class="header-anchor" href="#表示层-presentation-layer" aria-label="Permalink to &quot;表示层（Presentation Layer）&quot;">​</a></h3><p><img src="'+C+'" alt=""></p><p>表示层无特定设备，主要由主机操作系统实现，表示层对上层数据或信息进行变换以保证一个主机应用层信息可以被另一个主机的应用程序理解。表示层的数据转换包括数据的加密、压缩、格式转换等，主要任务是确保不同系统间的数据互操作性，其核心功能包括：</p><ul><li>语法转换：统一数据表示形式（如将 EBCDIC 编码转换为 ASCII）</li><li>语义转换：解析数据含义（如 XML、JSON 格式解析）</li><li>安全服务：通过 SSL/TLS 实现数据加密（如 HTTPS）</li></ul><p>关键协议：</p><ul><li>ASN.1（抽象语法标记法）：定义数据结构的标准表示</li><li>JPEG/MPEG：图像 / 视频压缩算法</li><li>SSL/TLS：传输层安全协议，虽属 TCP/IP 体系，但实现表示层功能</li></ul><p>实际应用中，其功能常由应用层协议（如 FTP 的二进制 / ASCII 模式）或传输层扩展（如 TLS）实现</p><h3 id="应用层-application-layer" tabindex="-1">应用层（Application Layer） <a class="header-anchor" href="#应用层-application-layer" aria-label="Permalink to &quot;应用层（Application Layer）&quot;">​</a></h3><p><img src="'+I+'" alt=""></p><p>直接为用户应用程序提供网络服务，定义应用数据的格式和交互规则，常见服务包括：</p><ul><li>文件传输：FTP（文件传输协议）、TFTP（简单文件传输协议）</li><li>网页浏览：HTTP（超文本传输协议）、HTTPS（加密 HTTP）</li><li>电子邮件：SMTP（发送）、POP3/IMAP（接收）</li><li>远程登录：Telnet（不安全）、SSH（安全外壳协议）</li><li>关键协议：</li><li>DNS（域名系统）：将域名解析为 IP 地址</li><li>SNMP（简单网络管理协议）：监控网络设备状态</li><li>NTP（网络时间协议）：同步设备时间</li></ul><p>特点：与用户直接交互，是网络服务的最终呈现层，协议种类繁多且不断扩展</p><h2 id="tcp-ip-协议-4-层" tabindex="-1">TCP/IP 协议 4 层 <a class="header-anchor" href="#tcp-ip-协议-4-层" aria-label="Permalink to &quot;TCP/IP 协议 4 层&quot;">​</a></h2><p><img src="'+q+'" alt=""></p><p>TCP/IP（Transmission Control Protocol/Internet Protocol）是互联网的核心通信协议栈，采用四层分层设计，将复杂的网络通信分解为独立的功能模块。将OSI模型中的上三层，即应用层、表示层和会话层合并成了应用层，将OSI参考模型中的下两层，即数据链路层和物理层合并成了网络接口层，由于除了这两层之外TCP/IP参考模型和OSI参考模型完全一致，这里无需再单独介绍，大家直接参考上一节内容即可。与OSI参考模型相比，TCP/IP模型更为简洁，但两者在功能上有一定的对应关系，具体的TCP/IP 模型与 OSI 模型的关系如下表所示：</p><table tabindex="0"><thead><tr><th>TCP/IP 模型</th><th>对应的 OSI 模型</th><th>功能</th></tr></thead><tbody><tr><td>网络接口层（物理层 + 数据链路层）</td><td>物理层、数据链路层</td><td>TCP/IP 将物理层与数据链路层合并，简化实现。</td></tr><tr><td>网络层（IP 协议）</td><td>网络层</td><td>功能类似，但 TCP/IP 仅支持无连接通信，而 OSI 同时支持面向连接和无连接。</td></tr><tr><td>传输层（TCP/UDP）</td><td>传输层</td><td>功能一致，TCP/IP 的 UDP 提供无连接选项，更灵活。</td></tr><tr><td>应用层（合并会话层、表示层）</td><td>会话层、表示层、应用层</td><td>TCP/IP 将上层功能整合，如 HTTPS 同时处理加密（表示层）和请求响应（应用层）。</td></tr></tbody></table><p>TCP/IP 四层协议通过<strong>分层设计</strong>和<strong>协议协作</strong>，实现了高效、灵活的网络通信，四层结构降低了实现复杂度，适合大规模网络部署，并且支持异构网络互联，成为互联网的事实标准。</p><h2 id="practics-1" tabindex="-1">Practics <a class="header-anchor" href="#practics-1" aria-label="Permalink to &quot;Practics&quot;">​</a></h2><table tabindex="0"><thead><tr><th>【例题】在OSI七层体系结构中，数据传输单位为“帧（Frame）”的层次是（ ）A. 物理层B. 数据链路层C. 网络层D. 传输层答案：B解析：根据材料内容，各层对应的传输单位明确如下：物理层传输单位是比特流，数据链路层是帧，网络层是数据包，传输层是数据段。因此数据传输单位为“帧”的层次是数据链路层，正确答案为B。</th></tr></thead></table><table tabindex="0"><thead><tr><th>【例题】关于TCP/IP四层模型与OSI七层模型的对应关系，下列说法正确的是（ ）A. TCP/IP的网络接口层仅对应OSI的物理层B. TCP/IP的应用层对应OSI的应用层C. TCP/IP的传输层与OSI的传输层功能一致D. TCP/IP的网络层同时支持面向连接和无连接通信答案：C解析：A选项错误，TCP/IP的网络接口层对应OSI的物理层和数据链路层；B选项错误，TCP/IP的应用层整合了OSI的会话层、表示层和应用层功能；C选项正确，材料明确提到两者传输层功能一致，均包含可靠/不可靠传输服务等核心功能；D选项错误，TCP/IP的网络层仅支持无连接通信，OSI的网络层同时支持面向连接和无连接通信。因此正确答案为C。</th></tr></thead></table><h2 id="计算机网络的性能指标" tabindex="-1">计算机网络的性能指标 <a class="header-anchor" href="#计算机网络的性能指标" aria-label="Permalink to &quot;计算机网络的性能指标&quot;">​</a></h2><p>计算机网络的性能指标是衡量网络传输效率和质量的重要参数，这些指标共同影响网络的整体性能，优化它们可以提高网络的响应速度、稳定性和吞吐能力。下面我将用浅显易懂的例子来帮助大家理解下面这些指标，主要包括以下内容：</p><h2 id="速率-data-rate" tabindex="-1">速率（Data Rate） <a class="header-anchor" href="#速率-data-rate" aria-label="Permalink to &quot;速率（Data Rate）&quot;">​</a></h2><p><img src="'+g+'" alt=""></p><p>速率是指单位时间内传输的数据量，也称为数据率或者比特率，类比可以理解成河流中每s流过的水分子的数量，通常以比特每秒（bit/s）为单位，如 Mb/s、Gb/s，表示数据的发送速度。</p><h2 id="带宽-bandwidth-和吞吐量-throughput" tabindex="-1">带宽（Bandwidth）和吞吐量（Throughput） <a class="header-anchor" href="#带宽-bandwidth-和吞吐量-throughput" aria-label="Permalink to &quot;带宽（Bandwidth）和吞吐量（Throughput）&quot;">​</a></h2><h3 id="带宽-bandwidth" tabindex="-1">带宽（Bandwidth） <a class="header-anchor" href="#带宽-bandwidth" aria-label="Permalink to &quot;带宽（Bandwidth）&quot;">​</a></h3><p><img src="'+_+'" alt=""></p><p>在计算机网络当中，带宽一般用来描述网络中某通道传送数据的能力，一般用单位时间内能传输的最高数据量来进行描述，单位与速率相同（bps），带宽越高，网络潜在传输能力越强，带宽的单位是bit/s，即“比特每秒”。同样用水流的例子举例就是，不同的河道能承受的最大水流量不同，带宽就是某个河道能承受的最大水流量。</p><h3 id="吞吐量-throughput" tabindex="-1">吞吐量（Throughput） <a class="header-anchor" href="#吞吐量-throughput" aria-label="Permalink to &quot;吞吐量（Throughput）&quot;">​</a></h3><p>吞吐量指单位时间内实际成功传输的数据量，反映网络的实际传输效率，通常低于理论带宽。以水流的例子来讲，带宽是指这个河道最大的水流传输率，而吞吐量则是这个河道的实际水流传输量。所以带宽是个理论值，而吞吐量则是个实际值。</p><h2 id="时延-delay-latency" tabindex="-1">时延（Delay/Latency） <a class="header-anchor" href="#时延-delay-latency" aria-label="Permalink to &quot;时延（Delay/Latency）&quot;">​</a></h2><p><img src="'+S+'" alt=""></p><p>时延是指数据从发送端到接收端所需的时间，我们日常说的网络有延迟实际上更加专业一点儿的术语就是时延。时延包括发送时延、传播时延、处理时延和排队时延，会影响网络实时性。</p><ol><li><p><strong>发送时延</strong>：主机或者路由器发送一个数据帧所花费的时间，即从发送第一个比特开始，到最终完成所有数据发送所消耗的时间。</p></li><li><p>**传播时延（Propagation Delay）😗*数据在传输介质（如光纤、电缆）中传播所需的时间，数据在不同的传输介质上的传输效率不同，因此影响传播时延的东西包括：传输距离、介质类型（光纤 vs. 铜缆）。</p></li><li><p><strong>处理时延（Processing Delay）</strong></p></li></ol><p>路由器/交换机等设备处理数据（如检查包头、计算路由）所需的时间，例如路由器检查会 IP 包头并转发数据，通常为时间为微秒（μs）级。受设备性能、网络协议复杂度等因素影响。</p><ol><li><strong>排队时延（Queuing Delay）</strong></li></ol><p>排队时延是指数据在路由器/交换机的缓冲区中等待处理的时间，网络拥塞时，数据包需排队等待，时延可能从毫秒（ms）到秒（s）不等。 受到网络流量、缓冲区大小、调度算法（如 FIFO、优先级队列）等因素的影响。</p><ol><li><p><strong>总时延（Total Delay）</strong></p></li><li><p><strong>关键区别</strong></p></li></ol><table tabindex="0"><thead><tr><th>时延类型</th><th>主要影响因素</th><th>典型值</th><th>优化方法</th></tr></thead><tbody><tr><td>发送时延</td><td>数据大小、带宽</td><td>毫秒~秒</td><td>提高带宽、压缩数据</td></tr><tr><td>传播时延</td><td>距离、介质</td><td>毫秒级</td><td>减少物理距离（如 CDN）</td></tr><tr><td>处理时延</td><td>设备性能</td><td>微秒级</td><td>升级硬件（如 ASIC 加速）</td></tr><tr><td>排队时延</td><td>网络拥塞</td><td>可变（ms~s）</td><td>流量控制（如 QoS）</td></tr></tbody></table><h2 id="时延带宽积-delay-bandwidth-product" tabindex="-1">时延带宽积（Delay-Bandwidth Product） <a class="header-anchor" href="#时延带宽积-delay-bandwidth-product" aria-label="Permalink to &quot;时延带宽积（Delay-Bandwidth Product）&quot;">​</a></h2><p>表示网络中可以同时传输但尚未确认的数据量，计算公式为 <strong>时延 × 带宽</strong>，反映网络的“管道容量”。通俗点儿解释就是，假设数据发送端会连续的发送数据，当发送的第一个比特已经达到接收端之后，这时候发送端已经发送了的数据的数量就是时延带宽积。</p><h2 id="利用率-utilization" tabindex="-1">利用率（Utilization） <a class="header-anchor" href="#利用率-utilization" aria-label="Permalink to &quot;利用率（Utilization）&quot;">​</a></h2><p>指网络资源的使用效率，如<strong>信道利用率 = 实际吞吐量 / 最大带宽</strong>，过高可能导致拥塞。简单来说就是网络带宽一般是跑不满的，实际的网络传输速率到带宽的百分之几十，那么这个网络的利用率就是百分之几十。</p><h2 id="往返时间-rtt-round-trip-time" tabindex="-1">往返时间（RTT, Round-Trip Time） <a class="header-anchor" href="#往返时间-rtt-round-trip-time" aria-label="Permalink to &quot;往返时间（RTT, Round-Trip Time）&quot;">​</a></h2><p>往返时间（RTT, Round-Trip Time）是计算机网络中非常重要性能指标，它指数据从发送端到接收端并返回确认所需的时间，影响 TCP 等协议的传输效率。</p><h2 id="practics-2" tabindex="-1">Practics <a class="header-anchor" href="#practics-2" aria-label="Permalink to &quot;Practics&quot;">​</a></h2><table tabindex="0"><thead><tr><th>【例题】下列选项中，属于计算机网络中“传播时延”主要影响因素的是（ ）A. 数据长度、网络带宽B. 传输距离、传输介质类型C. 路由器设备性能、协议复杂度D. 网络流量、缓冲区调度算法答案：B解析：根据材料内容，传播时延是数据在传输介质中传播所需的时间，其主要影响因素为传输距离和介质类型（如光纤与铜缆的传播速度不同）；A选项是发送时延的影响因素，C选项是处理时延的影响因素，D选项是排队时延的影响因素，因此正确答案为B。</th></tr></thead></table><table tabindex="0"><thead><tr><th>【例题】关于计算机网络中的带宽与吞吐量，下列说法正确的是（ ）A. 吞吐量是网络通道的理论最大数据传输能力，通常高于带宽B. 带宽和吞吐量的单位不同，前者以“比特每秒”计量，后者以“字节每秒”计量C. 吞吐量是单位时间内实际成功传输的数据量，通常低于理论带宽D. 网络利用率越高，吞吐量越接近带宽，因此应追求100%的信道利用率答案：C解析：A选项错误，带宽是理论最大传输能力，吞吐量是实际传输量，通常低于带宽；B选项错误，带宽与吞吐量单位一致，均为“比特每秒（bps）”；C选项正确，材料明确说明吞吐量是实际成功传输的数据量，受网络拥塞等因素影响，通常低于理论带宽；D选项错误，信道利用率过高会导致网络拥塞，反而降低传输效率，无需追求100%利用率，因此正确答案为C。</th></tr></thead></table>',171)])])}const L=t(y,[["render",f]]);export{U as __pageData,L as default};
